import{_ as e,o as i,c as l,a2 as t}from"./chunks/framework.DnrXFDHb.js";const r="/images/screenshots/wallet-recharge.png",o="/images/screenshots/wallet-redeem-code.png",u=JSON.parse('{"title":"充值 / 续费","description":"完成 CCWS 账号充值、续费或兑换码兑换，确认账号额度可以支持 ChatGPT（Codex）和 API 调用。","frontmatter":{"title":"充值 / 续费","description":"完成 CCWS 账号充值、续费或兑换码兑换，确认账号额度可以支持 ChatGPT（Codex）和 API 调用。"},"headers":[],"relativePath":"guide/recharge.md","filePath":"guide/recharge.md","lastUpdated":1783061751000}'),s={name:"guide/recharge.md"};function n(d,a,h,c,p,_){return i(),l("div",null,[...a[0]||(a[0]=[t('<h1 id="充值-续费" tabindex="-1">充值 / 续费 <a class="header-anchor" href="#充值-续费" aria-label="Permalink to &quot;充值 / 续费&quot;">​</a></h1><p>这一页讲怎么给账号充钱、续套餐，以及付完款怎么确认到账。</p><p><img src="'+r+'" alt="充值页面" loading="lazy"></p><h2 id="充值" tabindex="-1">充值 <a class="header-anchor" href="#充值" aria-label="Permalink to &quot;充值&quot;">​</a></h2><ol><li>登录 CCWS 控制台。</li><li>进「钱包」页面。</li><li>在「添加资金」区域选一个固定金额，或者自己填一个金额。</li><li>选支付方式（目前支持支付宝）。</li><li>看清楚金额，付款。</li><li>回控制台，确认余额已经更新。</li></ol><h2 id="兑换码兑换" tabindex="-1">兑换码兑换 <a class="header-anchor" href="#兑换码兑换" aria-label="Permalink to &quot;兑换码兑换&quot;">​</a></h2><p>有兑换码的话，在钱包页面底部就能换：</p><p><img src="'+o+'" alt="兑换码兑换" loading="lazy"></p><ol><li>找到「有兑换码吗？」那一栏。</li><li>输入兑换码。</li><li>点「兑换额度」。</li><li>兑换完刷新一下页面，确认额度到账了。</li></ol><h2 id="付了钱没到账" tabindex="-1">付了钱没到账 <a class="header-anchor" href="#付了钱没到账" aria-label="Permalink to &quot;付了钱没到账&quot;">​</a></h2><p>遇到付款后余额没变，按这个顺序查：</p><ul><li>等 1 到 3 分钟，刷新页面再看看。</li><li>查一下支付订单是不是成功了。</li><li>把订单号、付款截图和账号信息都存好。</li><li>联系 QQ 售后群或管理员处理。</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p>充好钱、确认额度能用了，接着去 <a href="/guide/api-key">创建 API Key</a>。</p>',14)])])}const g=e(s,[["render",n]]);export{u as __pageData,g as default};
